    # Parse the URI
    parsed = urlparse.urlparse(uri)

    scheme = parsed.scheme.lower()
    if not scheme:
        raise ValueError('uri has no scheme')

    netloc = parsed.netloc
    path = parsed.path

    # Override host if provided
    if host is not None:
        netloc = host

    if not netloc:
        raise ValueError('uri has no host')

    # Handle host override - need to parse netloc for port
    # Split netloc into host and port
    # Handle IPv6 addresses
    if netloc.startswith('['):
        # IPv6
        bracket_end = netloc.find(']')
        if bracket_end == -1:
            raise ValueError('invalid IPv6 address')
        hostname = netloc[:bracket_end + 1].lower()
        rest = netloc[bracket_end + 1:]
        if rest.startswith(':'):
            port_str = rest[1:]
        else:
            port_str = None
    else:
        if ':' in netloc:
            parts = netloc.rsplit(':', 1)
            hostname = parts[0].lower()
            port_str = parts[1]
        else:
            hostname = netloc.lower()
            port_str = None

    if not hostname:
        raise ValueError('uri has no hostname')

    # Validate port
    if port_str is not None:
        if port_str == '':
            port_str = None
        else:
            # Validate port is a valid integer
            try:
                port_num = int(port_str)
                if port_num <= 0 or port_num > 65535:
                    raise ValueError('invalid port: {}'.format(port_str))
                # Check it's actually an integer (no floats, no letters)
                if str(port_num) != port_str:
                    raise ValueError('invalid port: {}'.format(port_str))
            except ValueError as e:
                if 'invalid port' in str(e):
                    raise
                raise ValueError('invalid port: {}'.format(port_str))

    # Remove default ports
    default_ports = {'http': '80', 'https': '443'}
    if port_str is not None:
        if default_ports.get(scheme) == port_str:
            port_str = None

    # Reconstruct netloc
    if port_str is not None:
        netloc = '{}:{}'.format(hostname, port_str)
    else:
        netloc = hostname

    # Handle path
    if not path:
        path = '/'

    # Percent-encode the path (spaces etc.)
    # Re-encode path: decode then encode properly
    path = urlparse.quote(urlparse.unquote(path), safe='/:@!$&\'()*+,;=-._~')

    # Encode hostname spaces
    netloc_encoded = urlparse.quote(netloc, safe=':[]@!$&\'()*+,;=-._~')

    result = '{}://{}{}'.format(scheme, netloc_encoded, path)

    return result
